# Unit 6 Parsons authoring, part B: 6.4 Navbar, 6.5 Cards, 6.6 Forms
from p6a import P, D, Dt, Pc
def A(c, t, h='https://www.nasa.gov'): return '<a class="%s" href="%s">%s</a>' % (c, h, t)
